// Real-data scenario: Kendall Square / East Cambridge, MA.
// Geometry, one-way rules, lanes and speed limits come from OpenStreetMap; demand and turning
// shares come from City of Cambridge sensor counts. Generated by research/scripts/build_kendall.py.

import { boundaryNodeId, buildFromSpec, type NetworkSpec } from '../network';
import { COMMON_LIMITATIONS, type CityScenario, type DemandProfile, type Period, type Preset } from '../scenario';
import type { Heading, Turn } from '../types';
import data from './kendall.data.json';

const net = buildFromSpec(data as unknown as NetworkSpec);
const OPP: Record<Heading, Heading> = { N: 'S', S: 'N', E: 'W', W: 'E' };

/** Link carrying traffic that enters signal `sid` from `side` (keys in the data file are `sid:side`). */
function approachLink(key: string): string | null {
  const [sid, side] = key.split(':') as [string, Heading];
  const id = net.inLinks[sid]?.find((l) => net.links[l].heading === OPP[side]);
  return id ?? null;
}

interface RawPeriod {
  label: string;
  entries: Record<string, { vph: number; source: 'measured' | 'modeled' }>;
  busEntries: Record<string, number>;
  turns: Record<string, Partial<Record<Turn, number>>>;
  busTurns: Record<string, Partial<Record<Turn, number>>>;
  observed: Record<string, number>;
}
const raw = data.periods as unknown as Record<Period, RawPeriod>;

const byLink = <T,>(rec: Record<string, T>) => {
  const out: Record<string, T> = {};
  for (const [k, v] of Object.entries(rec)) {
    const l = approachLink(k);
    if (l) out[l] = v;
  }
  return out;
};

function profile(p: RawPeriod): DemandProfile {
  const entries: Record<string, number> = {};
  for (const [k, v] of Object.entries(p.entries)) {
    const [sid, side] = k.split(':') as [string, Heading];
    entries[`${boundaryNodeId(sid, side)}>${sid}`] = v.vph;
  }
  const busEntries: Record<string, number> = {};
  for (const [k, v] of Object.entries(p.busEntries)) {
    const [sid, side] = k.split(':') as [string, Heading];
    const id = `${boundaryNodeId(sid, side)}>${sid}`;
    if (net.links[id]) busEntries[id] = v;
  }
  // Unsensored intersections fall back to 10% left / 10% right.
  return { entries, busEntries, turns: byLink(p.turns), busTurns: byLink(p.busTurns), turnL: 0.1, turnR: 0.1 };
}

const PERIODS: Record<Period, DemandProfile> = { AM: profile(raw.AM), MIDDAY: profile(raw.MIDDAY), PM: profile(raw.PM) };
const OBSERVED = { AM: byLink(raw.AM.observed), MIDDAY: byLink(raw.MIDDAY.observed), PM: byLink(raw.PM.observed) };
const modeledEntries = Object.entries(raw.PM.entries)
  .filter(([, v]) => v.source === 'modeled')
  .map(([k]) => {
    const [sid, side] = k.split(':') as [string, Heading];
    return `${net.links[`${boundaryNodeId(sid, side)}>${sid}`].name.replace(/ [NESW]B$/, '')} into ${net.nodes[sid].name}`;
  });

const entriesFrom = (side: Heading) => net.entries.filter((e) => net.links[e].heading === OPP[side]);

